def acha_package_json(cwd):
    """package.json mais proximo subindo a partir de cwd, como o npm resolve."""
    d = os.path.abspath(cwd)
    while True:
        p = os.path.join(d, "package.json")
        if os.path.isfile(p):
            return p
        pai = os.path.dirname(d)
        if pai == d:
            return None
        d = pai


def classifica_script(cwd, nome_script, profundidade=0):
    """O que `npm/pnpm/yarn <nome_script>` executa de verdade.

    "runner" (jest/vitest), "recursivo" (pnpm -r), "outro" (ex: pytest via
    wrapper) ou None quando nao da pra saber -- ai a regra segue conservadora.
    Existe porque `npm test` nem sempre e jest: no repo underdogs ele chama
    pytest via node, e o hook barrava isso (17/10/2026).
    """
    if profundidade > 3:
        return None
    p = acha_package_json(cwd)
    if not p:
        return None
    try:
        with open(p) as fh:
            corpo = (json.load(fh).get("scripts") or {}).get(nome_script)
    except Exception:
        return None
    if not isinstance(corpo, str):
        return None
    if re.search(r"(^|[\s/;&|(])(jest|vitest)(\s|$)", corpo):
        return "runner"
    if re.search(r"\bpnpm\b.*\s(-r|--recursive)(\s|$)", corpo):
        return "recursivo"
    # script que so delega para outro script: segue a cadeia
    delega = re.search(r"\b(?:npm|pnpm|yarn)\s+(?:run\s+)?(test[\w:-]*)", corpo)
    if delega and delega.group(1) != nome_script:
        return classifica_script(cwd, delega.group(1), profundidade + 1)
    return "outro"


