#!/usr/bin/env python3
"""Guarda de memoria da maquina local (hook PreToolUse/Bash).

Contexto: 01/09/2026 um `npm run build` com heap de 8 GB disparado por um
subagente, somado a 10 subagentes rodando jest em paralelo, estourou os 15 GB de
RAM + 4 GB de swap. O OOM killer matou o node e o systemd derrubou o scope
inteiro da IDE (Antigravity) junto, porque o processo era filho do terminal
integrado.

Regras:
  1. NEGA --max-old-space-size acima de LIMITE_HEAP_MB
  2. NEGA jest/vitest sem limite de workers; PERGUNTA em script recursivo do pnpm
  3. PERGUNTA antes de um build quando a memoria disponivel esta baixa

Registrado em ~/.claude/settings.json (escopo do usuario) de proposito: o limite
e da maquina, e settings de projeto nao sobem a hierarquia de diretorios -- cada
repo do work-leapy e seu proprio project root.

Desenho: a analise e feita comando por comando, sobre tokens produzidos por
shlex (que respeita quotes). Analisar a string crua com regex gera
falso-positivo em `grep "jest\\|vitest"` e em heredoc que documenta a flag.
Bateria de regressao em testa-guard-memoria.py, ao lado.
"""
import json
import re
import shlex
import sys

LIMITE_HEAP_MB = 4096      # teto de heap do node nesta maquina (15 GB de RAM)
MIN_MEM_BUILD_MB = 4096    # piso de memoria disponivel pra liberar build direto
MAX_WORKERS_SUGERIDO = 2

# Comandos que apenas LEEM ou movem texto: podem receber as strings perigosas
# como argumento de busca sem executar nada pesado.
LEITORES = {
    "grep", "rg", "ag", "cat", "echo", "printf", "head", "tail", "less", "more",
    "sed", "awk", "jq", "find", "ls", "wc", "git", "diff", "sort", "uniq", "tee",
    "cut", "tr", "xargs", "rm", "cp", "mv", "mkdir", "touch", "chmod", "test",
}
# Prefixos transparentes: o comando de verdade vem depois.
IGNORAVEIS = {"sudo", "time", "env", "nohup", "exec", "command", "then", "do", "if"}
GESTORES = {"npx", "bunx", "npm", "pnpm", "yarn"}
SUBCOMANDOS = {"run", "exec", "dlx", "--if-present", "-r", "--recursive"}
RUNNERS = {"jest", "vitest"}
BUILDERS = {"next", "nuxt", "vite", "astro", "tsc", "turbo"}
OPERADORES = {"|", "||", "&&", ";", "&", "|&"}


def responde(decisao, motivo):
    print(json.dumps({
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": decisao,
            "permissionDecisionReason": motivo,
        }
    }))
    sys.exit(0)


def mem_disponivel_mb():
    """RAM disponivel + swap livre, em MB. None se nao der pra ler."""
    try:
        valores = {}
        with open("/proc/meminfo") as fh:
            for linha in fh:
                campo, _, resto = linha.partition(":")
                valores[campo] = int(resto.split()[0])  # kB
        return (valores.get("MemAvailable", 0) + valores.get("SwapFree", 0)) // 1024
    except Exception:
        return None


def sem_heredoc(cmd):
    """Remove o CORPO de heredocs: documentar uma flag perigosa nao e executa-la."""
    saida = []
    linhas = cmd.split("\n")
    i = 0
    while i < len(linhas):
        linha = linhas[i]
        saida.append(linha)
        marcas = re.findall(r"<<-?\s*['\"]?([A-Za-z_][A-Za-z0-9_]*)['\"]?", linha)
        i += 1
        for marca in marcas:
            while i < len(linhas) and linhas[i].strip() != marca:
                i += 1
            if i < len(linhas):
                saida.append(linhas[i])
                i += 1
    return "\n".join(saida)


def comandos(cmd):
    """Quebra o script em comandos individuais, cada um como lista de tokens.

    Quebra por LINHA antes de tokenizar: shlex trata newline como espaco comum,
    entao sem isso um script que comeca com `echo` engoliria um `npx jest` na
    linha seguinte dentro do mesmo grupo -- e a cabeca `echo` (leitor) faria o
    grupo inteiro ser ignorado.
    """
    grupos = []
    for linha in cmd.split("\n"):
        if not linha.strip():
            continue
        try:
            lex = shlex.shlex(linha, posix=True, punctuation_chars=True)
            lex.whitespace_split = True
            tokens = list(lex)
        except ValueError:
            continue  # linha exotica (quote aberta): nao atrapalhar

        atual = []
        for token in tokens:
            if token in OPERADORES:
                if atual:
                    grupos.append(atual)
                atual = []
            else:
                atual.append(token)
        if atual:
            grupos.append(atual)
    return grupos


def cabeca(tokens):
    """(nome do comando, indice dele) pulando env vars, `cd <dir>` e prefixos."""
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", token):
            i += 1
            continue
        base = token.split("/")[-1]
        if base == "cd":
            i += 2  # pula o cd e o diretorio
            continue
        if base in IGNORAVEIS:
            i += 1
            continue
        return base, i
    return "", -1


def alvo_do_gestor(tokens, idx):
    """Primeiro argumento significativo depois de npx/npm/pnpm/yarn."""
    for token in tokens[idx + 1:]:
        if token.startswith("-") or token in SUBCOMANDOS:
            continue
        return token.split("/")[-1]
    return ""


def analisa(tokens):
    """Devolve (decisao, motivo) para um comando, ou None se estiver ok."""
    nome, idx = cabeca(tokens)
    if not nome or nome in LEITORES:
        return None

    args = tokens[idx + 1:]
    todos = tokens  # inclui atribuicoes de env (NODE_OPTIONS=...)

    # --- 1. heap do node acima do teto -------------------------------------
    for token in todos:
        heap = re.search(r"--max[-_]old[-_]space[-_]size=(\d+)", token)
        if heap and int(heap.group(1)) > LIMITE_HEAP_MB:
            return "deny", (
                f"Heap de {heap.group(1)} MB acima do teto de {LIMITE_HEAP_MB} MB desta "
                f"maquina (15 GB de RAM, 8 GB de swap). Em 01/09/2026 um build com 8192 MB "
                f"estourou a memoria e o OOM killer derrubou a IDE junto. Rode sem "
                f"NODE_OPTIONS, ou com no maximo --max-old-space-size={LIMITE_HEAP_MB}. Se o "
                f"build realmente precisar de mais heap, derrube o next dev e o Chrome "
                f"primeiro e rode num terminal FORA da IDE, para um OOM matar so o build."
            )

    # --- 2. runner de teste sem limite de workers --------------------------
    tem_limite = any(
        t.startswith("--maxWorkers") or t.startswith("--workspace-concurrency")
        or t in ("--runInBand", "-i", "-w")
        for t in args
    )
    alvo = alvo_do_gestor(tokens, idx) if nome in GESTORES else ""
    runner_direto = nome in RUNNERS or alvo in RUNNERS
    script_teste = (
        nome in {"npm", "pnpm", "yarn"}
        and bool(re.match(r"^test(:[\w-]+)?$", alvo))
    )
    recursivo = nome == "pnpm" and (
        any(t in ("-r", "--recursive") for t in args) or (script_teste and not runner_direto)
    )

    if not tem_limite and recursivo:
        return "ask", (
            f"Script de teste recursivo do pnpm: no monorepo leapy ele expande para "
            f"`pnpm -r --if-present test`, que roda 8 pacotes -- e cada um abre seus "
            f"proprios workers. Alternativa mais segura: "
            f"`pnpm -r --workspace-concurrency=1 --if-present <script>`, ou rodar pacote por "
            f"pacote com --maxWorkers={MAX_WORKERS_SUGERIDO}. Confirme so se souber que a "
            f"suite e pequena e a memoria esta folgada."
        )

    if not tem_limite and (runner_direto or script_teste):
        return "deny", (
            f"jest/vitest sem limite de workers: o default e nproc-1 (11 workers nesta "
            f"maquina de 12 CPUs), e com varios subagentes em paralelo isso estoura a RAM. "
            f"Repita com --maxWorkers={MAX_WORKERS_SUGERIDO} (ou --runInBand para um arquivo "
            f"so). Se for via npm/pnpm, chame o runner direto -- "
            f"`npx jest --maxWorkers={MAX_WORKERS_SUGERIDO} ...` -- ou passe "
            f"`-- --maxWorkers={MAX_WORKERS_SUGERIDO}`."
        )

    # --- 3. build com memoria apertada ------------------------------------
    faz_build = (
        (nome in BUILDERS and "build" in args)
        or (nome in GESTORES and (alvo == "build" or alvo.startswith("build:")))
        or (nome in GESTORES and alvo in BUILDERS and "build" in args)
    )
    if faz_build:
        disp = mem_disponivel_mb()
        if disp is not None and disp < MIN_MEM_BUILD_MB:
            return "ask", (
                f"So {disp} MB de memoria disponivel (RAM + swap) e este comando e um build. "
                f"Um next build sozinho passa de 4 GB. Antes de confirmar: derrube o next dev, "
                f"feche abas do Chrome, ou rode num terminal fora da IDE. Foi exatamente esta "
                f"combinacao que causou o OOM de 01/09/2026."
            )

    return None


def main():
    try:
        payload = json.load(sys.stdin)
    except Exception:
        sys.exit(0)

    cmd = ((payload.get("tool_input") or {}).get("command") or "")
    if not cmd.strip():
        sys.exit(0)

    grupos = comandos(sem_heredoc(cmd))
    if grupos is None:
        sys.exit(0)  # nao deu pra tokenizar: nao atrapalhar

    for tokens in grupos:
        veredito = analisa(tokens)
        if veredito:
            responde(*veredito)

    sys.exit(0)


if __name__ == "__main__":
    main()

